-- Preserve a custom room's original owner until a dedicated ownership-transfer RPC exists.
create or replace function public.protect_room_owner() returns trigger language plpgsql security definer set search_path=public as $$ begin if tg_op='DELETE' and old.role='owner' then raise exception 'Ownership transfer is required before removing an owner'; end if; if tg_op='UPDATE' and old.role='owner' and new.role <> 'owner' then raise exception 'Ownership transfer is required before changing an owner role'; end if; return coalesce(new,old); end $$;
drop trigger if exists protect_room_owner_trigger on public.room_members; create trigger protect_room_owner_trigger before update or delete on public.room_members for each row execute procedure public.protect_room_owner();
create or replace function public.create_room(room_name text, room_topic text, private_room boolean) returns uuid language plpgsql security definer set search_path=public as $$ declare new_id uuid; base_slug text; candidate text; suffix integer:=1; begin perform require_authenticated(); if char_length(trim(room_name)) not between 3 and 60 or char_length(coalesce(room_topic,''))>240 then raise exception 'Invalid room details'; end if; base_slug:=trim(both '-' from regexp_replace(lower(trim(room_name)),'[^a-z0-9]+','-','g')); if base_slug='' then raise exception 'Invalid room name'; end if; perform pg_advisory_xact_lock(hashtext(base_slug)); candidate:=base_slug; while exists(select 1 from rooms where slug=candidate) loop suffix:=suffix+1; candidate:=base_slug||'-'||suffix; end loop; insert into rooms(slug,name,topic,kind,is_private,created_by) values(candidate,trim(room_name),nullif(trim(room_topic),''),'custom',private_room,auth.uid()) returning id into new_id; insert into room_members(room_id,user_id,role) values(new_id,auth.uid(),'owner'); return new_id; end $$;
